const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const delhi = ee.Geometry.Point([77.2090, 28.6139]).buffer(20000); // 20km buffer around Delhi center
  const date = '2024-01-15';

  // 2. Data Acquisition - Sentinel-2 with cloud detection
  const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(delhi)
    .filterDate(date, '2024-01-16');

  const collectionSize = s2.size().getInfo();
  console.log(`Images found for ${date}: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the first image
  const image = s2.first();

  // 3. Cloud detection using QA60 band
  // Bit 10: Opaque clouds, Bit 11: Cirrus clouds
  const qa = image.select('QA60');
  const cloudBitMask = 1 << 10;
  const cirrusBitMask = 1 << 11;

  // Create cloud mask (1 = cloud, 0 = clear)
  const clouds = qa.bitwiseAnd(cloudBitMask).gt(0)
    .or(qa.bitwiseAnd(cirrusBitMask).gt(0));

  // 4. Calculate cloud coverage over Delhi area
  const stats = clouds.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: delhi,
    scale: 1000,
    maxPixels: 1e9
  });

  const cloudCover = stats.get('constant_mean').getInfo();
  const pixelCount = stats.get('constant_count').getInfo();

  console.log(`Cloud coverage: ${(cloudCover * 100).toFixed(1)}%`);
  console.log(`Valid pixels: ${pixelCount}`);

  // 5. Validation & Final Answer
  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
  } else if (cloudCover === null || isNaN(cloudCover)) {
    console.log("<answer>C3</answer>");
  } else if (cloudCover >= 0.99) { // 99% or more cloud coverage
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
